// Pre-generated 16-bit PCM WAV Data URI for Glass Bottle Bump / Clink Sound
const GLASS_CLINK_WAV =
  'data:audio/wav;base64,RIFFNScAAVdAVEZtdCAAEAAAAAEAAACsAhAAeAACADBkYXRhFScAA' +
  ''

// Pre-create pooled audio elements & prime them muted on page load to bypass Chrome click restrictions
const audioPool: HTMLAudioElement[] = []
let poolIdx = 0

if (typeof window !== 'undefined') {
  try {
    for (let i = 0; i < 6; i++) {
      const audio = new Audio(GLASS_CLINK_WAV)
      audio.muted = true
      // Play muted immediately to unlock HTML5 audio element permissions without click
      audio.play().then(() => {
        audio.pause()
        audio.currentTime = 0
        audio.muted = false
      }).catch(() => {})
      audioPool.push(audio)
    }
  } catch (e) {}
}

let audioCtx: AudioContext | null = null

function getAudioContext(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  return audioCtx
}

// Auto-prime audio pool and context on any mouse movement or window event
if (typeof window !== 'undefined') {
  const prime = () => {
    const ctx = getAudioContext()
    if (ctx && ctx.state === 'suspended') {
      ctx.resume().catch(() => {})
    }
    audioPool.forEach((a) => {
      if (a.muted) {
        a.muted = false
      }
    })
  }

  window.addEventListener('mousemove', prime, { passive: true })
  window.addEventListener('pointermove', prime, { passive: true })
  window.addEventListener('mouseenter', prime, { passive: true })
  window.addEventListener('pointerdown', prime, { passive: true })
}

export function playGlassClinkSound() {
  try {
    // Primary Engine: HTML5 Audio Pool (Bypasses Chrome click restriction via muted auto-prime)
    if (audioPool.length > 0) {
      const sound = audioPool[poolIdx]
      poolIdx = (poolIdx + 1) % audioPool.length
      sound.muted = false
      sound.volume = 1.0
      sound.currentTime = 0
      const p = sound.play()
      if (p !== undefined) {
        p.catch(() => {
          playWebAudioSynth()
        })
      }
    } else {
      playWebAudioSynth()
    }
  } catch (err) {
    playWebAudioSynth()
  }
}

function playWebAudioSynth() {
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    if (ctx.state === 'suspended') {
      ctx.resume().catch(() => {})
    }

    const now = ctx.currentTime
    const masterGain = ctx.createGain()
    masterGain.gain.setValueAtTime(0.9, now)
    masterGain.gain.exponentialRampToValueAtTime(0.001, now + 0.3)
    masterGain.connect(ctx.destination)

    const osc1 = ctx.createOscillator()
    osc1.type = 'sine'
    osc1.frequency.setValueAtTime(2350, now)
    osc1.frequency.exponentialRampToValueAtTime(2300, now + 0.2)

    const g1 = ctx.createGain()
    g1.gain.setValueAtTime(0.9, now)
    g1.gain.exponentialRampToValueAtTime(0.001, now + 0.22)

    osc1.connect(g1)
    g1.connect(masterGain)

    const osc2 = ctx.createOscillator()
    osc2.type = 'sine'
    osc2.frequency.setValueAtTime(4850, now)
    osc2.frequency.exponentialRampToValueAtTime(4700, now + 0.1)

    const g2 = ctx.createGain()
    g2.gain.setValueAtTime(0.5, now)
    g2.gain.exponentialRampToValueAtTime(0.001, now + 0.1)

    osc2.connect(g2)
    g2.connect(masterGain)

    osc1.start(now)
    osc2.start(now)
    osc1.stop(now + 0.25)
    osc2.stop(now + 0.12)
  } catch (e) {}
}
